-- KKMP Kerten content studio. Safe to re-run; explicit grants + RLS.
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'admin' check(role in ('admin','super_admin')),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.site_content(id text primary key default 'main' check(id='main'),payload jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.business_units(id uuid primary key default gen_random_uuid(),name text not null,category text not null default '',kbli_code text unique,description text not null default '',status_label text not null default '',risk_label text not null default '',sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.timeline_items(id uuid primary key default gen_random_uuid(),date_label text not null,title text not null,description text not null default '',sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint timeline_items_date_title_unique unique(date_label,title));
create table if not exists public.gallery_items(id uuid primary key default gen_random_uuid(),title text not null,category text not null default '',description text not null default '',image_url text not null,storage_path text,sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),name text not null,role text not null,bio text not null default '',image_url text,sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.testimonials(id uuid primary key default gen_random_uuid(),quote text not null,author text not null,role text not null default '',sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists business_units_public_order_idx on public.business_units(is_published,sort_order);
create index if not exists timeline_items_public_order_idx on public.timeline_items(is_published,sort_order);
create index if not exists gallery_items_public_order_idx on public.gallery_items(is_published,sort_order);
create index if not exists team_members_public_order_idx on public.team_members(is_published,sort_order);
create index if not exists testimonials_public_order_idx on public.testimonials(is_published,sort_order);
create or replace function private.is_kkmp_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admin_users where user_id=(select auth.uid()) and is_active=true); $$;
revoke all on function private.is_kkmp_admin() from public,anon;
grant execute on function private.is_kkmp_admin() to authenticated;
alter table public.admin_users enable row level security;
alter table public.site_content enable row level security;
alter table public.business_units enable row level security;
alter table public.timeline_items enable row level security;
alter table public.gallery_items enable row level security;
alter table public.team_members enable row level security;
alter table public.testimonials enable row level security;
drop policy if exists "Admin can read own KKMP access" on public.admin_users;
create policy "Admin can read own KKMP access" on public.admin_users for select to authenticated using((select auth.uid())=user_id or (select private.is_kkmp_admin()));
drop policy if exists "KKMP admins manage admin access" on public.admin_users;
create policy "KKMP admins manage admin access" on public.admin_users for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read site content" on public.site_content;
create policy "Public can read site content" on public.site_content for select to anon,authenticated using(true);
drop policy if exists "KKMP admins manage site content" on public.site_content;
create policy "KKMP admins manage site content" on public.site_content for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read published business units" on public.business_units;
create policy "Public can read published business units" on public.business_units for select to anon,authenticated using(is_published=true);
drop policy if exists "KKMP admins manage business units" on public.business_units;
create policy "KKMP admins manage business units" on public.business_units for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read published timeline" on public.timeline_items;
create policy "Public can read published timeline" on public.timeline_items for select to anon,authenticated using(is_published=true);
drop policy if exists "KKMP admins manage timeline" on public.timeline_items;
create policy "KKMP admins manage timeline" on public.timeline_items for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read published gallery" on public.gallery_items;
create policy "Public can read published gallery" on public.gallery_items for select to anon,authenticated using(is_published=true);
drop policy if exists "KKMP admins manage gallery" on public.gallery_items;
create policy "KKMP admins manage gallery" on public.gallery_items for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read published team" on public.team_members;
create policy "Public can read published team" on public.team_members for select to anon,authenticated using(is_published=true);
drop policy if exists "KKMP admins manage team" on public.team_members;
create policy "KKMP admins manage team" on public.team_members for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
drop policy if exists "Public can read published testimonials" on public.testimonials;
create policy "Public can read published testimonials" on public.testimonials for select to anon,authenticated using(is_published=true);
drop policy if exists "KKMP admins manage testimonials" on public.testimonials;
create policy "KKMP admins manage testimonials" on public.testimonials for all to authenticated using((select private.is_kkmp_admin())) with check((select private.is_kkmp_admin()));
grant usage on schema public to anon,authenticated;
grant select on public.site_content,public.business_units,public.timeline_items,public.gallery_items,public.team_members,public.testimonials to anon,authenticated;
grant select,insert,update,delete on public.admin_users,public.site_content,public.business_units,public.timeline_items,public.gallery_items,public.team_members,public.testimonials to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('kkmp-media','kkmp-media',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=10485760,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Public can view KKMP media" on storage.objects;
create policy "Public can view KKMP media" on storage.objects for select to anon,authenticated using(bucket_id='kkmp-media');
drop policy if exists "KKMP admins upload media" on storage.objects;
create policy "KKMP admins upload media" on storage.objects for insert to authenticated with check(bucket_id='kkmp-media' and (select private.is_kkmp_admin()));
drop policy if exists "KKMP admins update media" on storage.objects;
create policy "KKMP admins update media" on storage.objects for update to authenticated using(bucket_id='kkmp-media' and (select private.is_kkmp_admin())) with check(bucket_id='kkmp-media' and (select private.is_kkmp_admin()));
drop policy if exists "KKMP admins delete media" on storage.objects;
create policy "KKMP admins delete media" on storage.objects for delete to authenticated using(bucket_id='kkmp-media' and (select private.is_kkmp_admin()));
